-- KaamSetu initial schema. Run in a new Supabase project SQL editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','worker','admin');
create type public.worker_availability as enum ('available','busy','unavailable');
create type public.enquiry_status as enum ('new','viewed','accepted','rejected','in_discussion','confirmed','completed','cancelled');
create table public.users (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'customer', full_name text not null, phone text unique, email text, is_blocked boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_profiles (user_id uuid primary key references public.users(id) on delete cascade, city text, area text, pincode text, profile_details text, created_at timestamptz not null default now());
create table public.worker_profiles (user_id uuid primary key references public.users(id) on delete cascade, bio text, experience_years int not null default 0 check(experience_years>=0), city text not null, area text, pincode text, service_radius_km int not null default 10, daily_rate numeric(10,2), hourly_rate numeric(10,2), per_sqft_rate numeric(10,2), project_rate numeric(12,2), availability public.worker_availability not null default 'available', verification_status text not null default 'pending' check(verification_status in ('pending','approved','rejected')), is_active boolean not null default true, public_phone boolean not null default false, avatar_path text, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text unique not null, slug text unique not null, icon text, description text, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table public.subcategories (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories(id) on delete cascade, name text not null, slug text not null, is_active boolean not null default true, unique(category_id,slug));
create table public.worker_skills (id uuid primary key default gen_random_uuid(), worker_id uuid not null references public.worker_profiles(user_id) on delete cascade, category_id uuid not null references public.categories(id), subcategory_id uuid references public.subcategories(id) on delete set null, skill_name text not null, unique(worker_id,category_id,skill_name));
create table public.locations (id uuid primary key default gen_random_uuid(), state text not null, city text not null, area text, pincode text, is_active boolean not null default true, unique(state,city,area,pincode));
create table public.worker_service_areas (worker_id uuid not null references public.worker_profiles(user_id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, primary key(worker_id,location_id));
create table public.worker_rates (id uuid primary key default gen_random_uuid(), worker_id uuid not null references public.worker_profiles(user_id) on delete cascade, category_id uuid not null references public.categories(id), rate_type text not null check(rate_type in ('daily','hourly','per_sqft','project')), amount numeric(12,2) not null check(amount>=0), currency char(3) not null default 'INR');
create table public.worker_portfolio (id uuid primary key default gen_random_uuid(), worker_id uuid not null references public.worker_profiles(user_id) on delete cascade, storage_path text not null, caption text, created_at timestamptz not null default now());
create table public.enquiries (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.users(id), worker_id uuid references public.worker_profiles(user_id), category_id uuid not null references public.categories(id), description text not null, state text, city text not null, area text, pincode text, required_date date, estimated_budget numeric(12,2), work_duration text, status public.enquiry_status not null default 'new', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.enquiry_status_history (id uuid primary key default gen_random_uuid(), enquiry_id uuid not null references public.enquiries(id) on delete cascade, changed_by uuid references public.users(id), old_status public.enquiry_status, new_status public.enquiry_status not null, note text, created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), enquiry_id uuid unique references public.enquiries(id) on delete set null, customer_id uuid not null references public.users(id), worker_id uuid not null references public.worker_profiles(user_id), rating int not null check(rating between 1 and 5), body text, is_visible boolean not null default true, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, title text not null, body text, href text, read_at timestamptz, created_at timestamptz not null default now());
create table public.verification_documents (id uuid primary key default gen_random_uuid(), worker_id uuid not null references public.worker_profiles(user_id) on delete cascade, storage_path text not null, document_type text not null, status text not null default 'pending' check(status in ('pending','approved','rejected')), reviewed_by uuid references public.users(id), created_at timestamptz not null default now());
create table public.complaints (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.users(id), worker_id uuid references public.worker_profiles(user_id), review_id uuid references public.reviews(id), enquiry_id uuid references public.enquiries(id), reason text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.admin_users (user_id uuid primary key references public.users(id) on delete cascade, granted_by uuid references public.users(id), created_at timestamptz not null default now());
create index worker_location_idx on public.worker_profiles(city,area,pincode) where is_active;
create index worker_availability_idx on public.worker_profiles(availability,experience_years);
create index enquiry_customer_idx on public.enquiries(customer_id,created_at desc);
create index enquiry_worker_idx on public.enquiries(worker_id,created_at desc);
create index reviews_worker_idx on public.reviews(worker_id,created_at desc) where is_visible;
create index notifications_user_idx on public.notifications(user_id,created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()) $$;
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.users where id=auth.uid() $$;
alter table public.users enable row level security; alter table public.customer_profiles enable row level security; alter table public.worker_profiles enable row level security; alter table public.categories enable row level security; alter table public.subcategories enable row level security; alter table public.worker_skills enable row level security; alter table public.locations enable row level security; alter table public.worker_service_areas enable row level security; alter table public.worker_rates enable row level security; alter table public.worker_portfolio enable row level security; alter table public.enquiries enable row level security; alter table public.enquiry_status_history enable row level security; alter table public.reviews enable row level security; alter table public.notifications enable row level security; alter table public.verification_documents enable row level security; alter table public.complaints enable row level security; alter table public.admin_users enable row level security;
create policy "users read self or admin" on public.users for select using(id=auth.uid() or public.is_admin());
create policy "users insert self" on public.users for insert with check(id=auth.uid() and role in ('customer','worker'));
create policy "users update self or admin" on public.users for update using(id=auth.uid() or public.is_admin()) with check((id=auth.uid() and role in ('customer','worker')) or public.is_admin());
create policy "customer profile owner/admin" on public.customer_profiles for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "worker profile public read active" on public.worker_profiles for select using(is_active or user_id=auth.uid() or public.is_admin());
create policy "worker profile owner/admin write" on public.worker_profiles for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "categories public read" on public.categories for select using(is_active or public.is_admin()); create policy "categories admin write" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "subcategories public read" on public.subcategories for select using(is_active or public.is_admin()); create policy "subcategories admin write" on public.subcategories for all using(public.is_admin()) with check(public.is_admin());
create policy "skills public read" on public.worker_skills for select using(exists(select 1 from public.worker_profiles w where w.user_id=worker_id and w.is_active) or worker_id=auth.uid() or public.is_admin()); create policy "skills owner/admin write" on public.worker_skills for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
create policy "locations public read" on public.locations for select using(is_active or public.is_admin()); create policy "locations admin write" on public.locations for all using(public.is_admin()) with check(public.is_admin());
create policy "service areas public read" on public.worker_service_areas for select using(exists(select 1 from public.worker_profiles w where w.user_id=worker_id and w.is_active) or worker_id=auth.uid() or public.is_admin()); create policy "service areas owner/admin write" on public.worker_service_areas for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
create policy "rates public read" on public.worker_rates for select using(exists(select 1 from public.worker_profiles w where w.user_id=worker_id and w.is_active) or worker_id=auth.uid() or public.is_admin()); create policy "rates owner/admin write" on public.worker_rates for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
create policy "portfolio public read" on public.worker_portfolio for select using(exists(select 1 from public.worker_profiles w where w.user_id=worker_id and w.is_active) or worker_id=auth.uid() or public.is_admin()); create policy "portfolio owner/admin write" on public.worker_portfolio for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
create policy "enquiry participants read" on public.enquiries for select using(customer_id=auth.uid() or worker_id=auth.uid() or public.is_admin()); create policy "customer create enquiry" on public.enquiries for insert with check(customer_id=auth.uid() and public.current_role()='customer'); create policy "participants update enquiry" on public.enquiries for update using(customer_id=auth.uid() or worker_id=auth.uid() or public.is_admin()) with check(customer_id=auth.uid() or worker_id=auth.uid() or public.is_admin());
create policy "history participants read" on public.enquiry_status_history for select using(exists(select 1 from public.enquiries e where e.id=enquiry_id and (e.customer_id=auth.uid() or e.worker_id=auth.uid())) or public.is_admin()); create policy "participants create history" on public.enquiry_status_history for insert with check(changed_by=auth.uid() and (exists(select 1 from public.enquiries e where e.id=enquiry_id and (e.customer_id=auth.uid() or e.worker_id=auth.uid())) or public.is_admin()));
create policy "reviews public visible" on public.reviews for select using(is_visible or customer_id=auth.uid() or public.is_admin()); create policy "customer create review" on public.reviews for insert with check(customer_id=auth.uid() and public.current_role()='customer' and exists(select 1 from public.enquiries e where e.id=enquiry_id and e.customer_id=auth.uid() and e.worker_id=reviews.worker_id and e.status='completed')); create policy "admin moderate reviews" on public.reviews for update using(public.is_admin()) with check(public.is_admin());
create policy "notification owner read" on public.notifications for select using(user_id=auth.uid() or public.is_admin()); create policy "notification owner update" on public.notifications for update using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "documents owner/admin only" on public.verification_documents for select using(worker_id=auth.uid() or public.is_admin()); create policy "worker submit documents" on public.verification_documents for insert with check(worker_id=auth.uid()); create policy "admin review documents" on public.verification_documents for update using(public.is_admin()) with check(public.is_admin());
create policy "complaint reporter/admin read" on public.complaints for select using(reporter_id=auth.uid() or public.is_admin()); create policy "user report complaint" on public.complaints for insert with check(reporter_id=auth.uid()); create policy "admin manage complaints" on public.complaints for update using(public.is_admin()) with check(public.is_admin());
create policy "admins read admins" on public.admin_users for select using(user_id=auth.uid() or public.is_admin()); create policy "admin manage admins" on public.admin_users for all using(public.is_admin()) with check(public.is_admin());
-- Restrict participants to status transitions: row-level policies alone would also let them rewrite job details.
create or replace function public.guard_enquiry_update() returns trigger language plpgsql security invoker set search_path=public as $$
begin
  if public.is_admin() then return new; end if;
  if auth.uid() = old.customer_id then
    if (to_jsonb(new) - 'status' - 'updated_at') <> (to_jsonb(old) - 'status' - 'updated_at') then raise exception 'Customers cannot edit enquiry details after submission'; end if;
    if new.status <> 'cancelled' or old.status in ('completed','rejected','cancelled') then raise exception 'Customer may only cancel an active enquiry'; end if;
    return new;
  end if;
  if auth.uid() = old.worker_id then
    if (to_jsonb(new) - 'status' - 'updated_at') <> (to_jsonb(old) - 'status' - 'updated_at') then raise exception 'Workers cannot edit customer enquiry details'; end if;
    if not ((old.status in ('new','viewed') and new.status in ('viewed','accepted','rejected')) or (old.status='accepted' and new.status in ('in_discussion','rejected')) or (old.status='in_discussion' and new.status in ('confirmed','rejected')) or (old.status='confirmed' and new.status='completed')) then raise exception 'Invalid worker enquiry status transition'; end if;
    return new;
  end if;
  raise exception 'Not an enquiry participant';
end; $$;
create trigger guard_enquiry_update before update on public.enquiries for each row execute function public.guard_enquiry_update();
